//! Closed generated bytes compared with native RtlVirtualUnwind; no guest code
//! is executed by either the golden producer or this parity test.
use emumee_core::x64_unwind::{self, Context, Image, Memory, Stack};
use serde::Deserialize;

const BASE: u64 = 0x100000;
const STACK: u64 = 0x200000;
#[derive(Deserialize)]
struct Value {
    value: Option<String>,
    stack_offset: Option<u64>,
    image_rva: Option<u64>,
}
impl Value {
    fn decode(&self) -> u64 {
        match (&self.value, self.stack_offset, self.image_rva) {
            (Some(value), None, None) => u64::from_str_radix(value, 16).unwrap(),
            (None, Some(offset), None) => STACK + offset,
            (None, None, Some(offset)) => BASE + offset,
            _ => panic!("Invalid generated pointer/value"),
        }
    }
}
#[derive(Deserialize)]
struct NativeContext {
    rip: Value,
    integer: Vec<Value>,
    xmm: Vec<[String; 2]>,
    eflags: u32,
    cs: u16,
    ss: u16,
}
impl NativeContext {
    fn decode(&self) -> Context {
        assert_eq!(self.integer.len(), 16);
        assert_eq!(self.xmm.len(), 16);
        let mut context = Context {
            rip: self.rip.decode(),
            eflags: self.eflags,
            cs: self.cs,
            ss: self.ss,
            ..Context::default()
        };
        for (i, v) in self.integer.iter().enumerate() {
            context.integer[i] = v.decode();
        }
        for (i, pair) in self.xmm.iter().enumerate() {
            context.xmm[i] = u64::from_str_radix(&pair[0], 16).unwrap() as u128
                | (u64::from_str_radix(&pair[1], 16).unwrap() as u128) << 64;
        }
        context
    }
}
#[derive(Deserialize)]
struct Block {
    rva: usize,
    hex: String,
}
#[derive(Deserialize)]
struct Word {
    offset: usize,
    data: Value,
}
#[derive(Deserialize)]
struct Case {
    name: String,
    directory_bytes: u32,
    pc_rva: u32,
    initial: NativeContext,
    expected: NativeContext,
    image_blocks: Vec<Block>,
    stack_words: Vec<Word>,
    handler_rva: u64,
    handler_data_rva: u64,
    establisher_offset: u64,
}
#[derive(Deserialize)]
struct Fixture {
    schema: String,
    os_build: u32,
    cases: Vec<Case>,
}
struct Bytes {
    image: Vec<u8>,
    stack: Vec<u8>,
}
impl Memory for Bytes {
    fn read(&mut self, address: u64, output: &mut [u8]) -> x64_unwind::Result<()> {
        let source = if (BASE..BASE + self.image.len() as u64).contains(&address) {
            self.image
                .get((address - BASE) as usize..(address - BASE) as usize + output.len())
        } else if (STACK..STACK + self.stack.len() as u64).contains(&address) {
            self.stack
                .get((address - STACK) as usize..(address - STACK) as usize + output.len())
        } else {
            None
        };
        output.copy_from_slice(source.ok_or(x64_unwind::Error::Read {
            address,
            size: output.len(),
        })?);
        Ok(())
    }
}

#[test]
fn x64_unwind_generated_frames_match_native_windows26200_contexts_and_body_handlers() {
    let golden: Fixture = serde_json::from_str(include_str!(
        "../../../tests/fixtures/native_x64_unwind_windows26200.json"
    ))
    .unwrap();
    assert_eq!(golden.schema, "emumee.native_unwind_generated.v1");
    assert_eq!(golden.os_build, 26200);
    assert_eq!(golden.cases.len(), 16);
    for case in golden.cases {
        let mut memory = Bytes {
            image: vec![0; 0x4000],
            stack: vec![0; 0x1000],
        };
        for block in case.image_blocks {
            assert_eq!(block.hex.len() % 2, 0);
            for i in 0..block.hex.len() / 2 {
                memory.image[block.rva + i] =
                    u8::from_str_radix(&block.hex[i * 2..i * 2 + 2], 16).unwrap();
            }
        }
        for word in case.stack_words {
            memory.stack[word.offset..word.offset + 8]
                .copy_from_slice(&word.data.decode().to_le_bytes());
        }
        let initial = case.initial.decode();
        assert_eq!(initial.rip, BASE + case.pc_rva as u64);
        let before = (memory.image.clone(), memory.stack.clone());
        let image = Image::parse(&mut memory, BASE, 0x4000, 0x200, case.directory_bytes).unwrap();
        let result = x64_unwind::unwind(
            &mut memory,
            &image,
            &initial,
            Stack {
                low: STACK,
                high: STACK + 0x1000,
            },
            1,
        )
        .unwrap_or_else(|e| panic!("{}: {e}", case.name));
        assert_eq!(result.caller, case.expected.decode(), "{}", case.name);
        assert_eq!(
            result.handler.map_or(0, |h| h.address - BASE),
            case.handler_rva,
            "{} handler",
            case.name
        );
        assert_eq!(
            result.handler.map_or(0, |h| h.data - BASE),
            case.handler_data_rva,
            "{} handler data",
            case.name
        );
        // Epilogues have no dispatchable handler. Our internal frame base is
        // not exposed as Windows' incidental epilogue diagnostic output.
        if !result.epilogue {
            assert_eq!(
                result.establisher - STACK,
                case.establisher_offset,
                "{} establisher",
                case.name
            );
        }
        assert_eq!(
            (memory.image, memory.stack),
            before,
            "{} mutated memory",
            case.name
        );
    }
}
